const body = $json.body || {};
const { callerName, callerEmail, requestedTimeISO, timeZone } = body;

// The standard JavaScript Date constructor correctly parses ISO 8601 strings with timezones.
const startDate = new Date(requestedTimeISO);

// Check if the date provided is valid after parsing.
if (isNaN(startDate.getTime())) {
  return [{
    json: {
      ok: false,
      message: `❌ Could not parse the date: ${requestedTimeISO}`
    }
  }];
}

// Calculate the end time 30 minutes after the start time.
const endDate = new Date(startDate.getTime() + 30 * 60000);

// This function correctly formats the end date back into an ISO string
// that includes the proper timezone offset, instead of converting it to Z (UTC).
function toLocalISOString(date) {
  const pad = (num) => String(num).padStart(2, '0');
  const tzOffset = -date.getTimezoneOffset();
  const diff = tzOffset >= 0 ? '+' : '-';
  return date.getFullYear() +
    '-' + pad(date.getMonth() + 1) +
    '-' + pad(date.getDate()) +
    'T' + pad(date.getHours()) +
    ':' + pad(date.getMinutes()) +
    ':' + pad(date.getSeconds()) +
    diff + pad(Math.floor(Math.abs(tzOffset) / 60)) +
    ':' + pad(Math.abs(tzOffset) % 60);
}

// IMPORTANT: We use the original and a correctly formatted end time
// This preserves the timezone and fixes the Google Calendar matching issue.
return [{
  json: {
    ok: true,
    callerName,
    callerEmail,
    start: requestedTimeISO,
    end: toLocalISOString(endDate),
    timeZone: timeZone || "America/Phoenix"
  }
}];

const appointmentData = $('1. Parse Incoming Data').first().json;
const start = new Date(appointmentData.start);
const newStart = new Date(start.getTime() + 60 * 60 * 1000); // +1 hour

// Format the suggested time in Spanish
const suggestedTimeSpanish = newStart.toLocaleString('es-ES', {
  weekday: 'long',
  day: 'numeric',
  month: 'long',
  year: 'numeric',
  hour: 'numeric',
  minute: '2-digit',
  timeZone: 'America/Phoenix'
});

return [{
  json: {
    ok: false,
    message: `Esa hora ya está reservada. Siguiente disponible: ${suggestedTimeSpanish}`,
    suggestedStart: suggestedTimeSpanish
  }
}];
